<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { ArrowRight, ArrowDown, Bell, Search, Refresh, Plus, Download, TrendCharts, Grid, Tickets, User, UserFilled, Service, Wallet, Setting, Document, TopRight, Check, Close, Monitor, Link, MoreFilled, CircleCheck, Clock, Warning, Switch, CreditCard, Headset, View, Select, Filter, CopyDocument } from '@element-plus/icons-vue';
import { api, useStaff } from './store';
import { ApiError, money, compactMoney, statusLabels, roleLabels, time, type Order, type Player, type Game, type Dashboard, type Settlement, type Audit, type ClubSettings, type Role } from '@stellar/core';
const staff=useStaff();
const nav=[{id:'dashboard',label:'概览看板',icon:Grid},{id:'orders',label:'订单工作台',icon:Tickets},{id:'players',label:'打手管理',icon:UserFilled},{id:'customers',label:'客户管理',icon:User},{id:'refunds',label:'退款售后',icon:Service},{id:'settlements',label:'报酬结算',icon:Wallet},{id:'settings',label:'俱乐部设置',icon:Setting},{id:'audit',label:'操作日志',icon:Document}];
const page=ref(location.hash.slice(1)||'dashboard');
const orders=ref<Order[]>([]),players=ref<Player[]>([]),games=ref<Game[]>([]),dashboard=ref<Dashboard|null>(null),settlements=ref<Settlement[]>([]),audit=ref<Audit[]>([]),settings=ref<ClubSettings|null>(null);
const loading=ref(true),refreshing=ref(false),busy=ref(false),loadError=ref(''),query=ref(''),globalSearch=ref(''),gameFilter=ref('all'),statusFilter=ref('all'),refundFilter=ref('pending'),playerFilter=ref('all'),settlementFilter=ref('all'),currentPage=ref(1),pageSize=8,sidebarCollapsed=ref(false);
const orderDrawer=ref(false),selectedOrder=ref<Order|null>(null),assignDialog=ref(false),assignPlayer=ref(''),assignReason=ref(''),refundDialog=ref(false),reviewApprove=ref(true),reviewNote=ref(''),playerDialog=ref(false),selectedPlayer=ref<Player|null>(null),editPrice=ref(0),roleDialog=ref(false),resetting=ref(false),customerDrawer=ref(false),customerId=ref('');
const settingsForm=reactive({name:'星曜电竞',commissionPercent:20,unpaidTimeoutMinutes:15,announcement:''});
let refreshTimer:ReturnType<typeof setInterval>;
const isAdmin=computed(()=>staff.session?.role==='admin');
const canFinance=computed(()=>['admin','finance'].includes(staff.session?.role||''));
const canDispatch=computed(()=>['admin','customer_service'].includes(staff.session?.role||''));
const availableNav=computed(()=>nav.filter(n=>!(['settings','audit'].includes(n.id)&&!isAdmin.value)&&!(n.id==='settlements'&&!canFinance.value)));
const pageLabel=computed(()=>nav.find(n=>n.id===page.value)?.label||'概览看板');
const onlinePlayers=computed(()=>players.value.filter(p=>p.approved&&p.available));
const pendingRefunds=computed(()=>orders.value.filter(o=>o.refundStatus==='pending'));
const filteredOrders=computed(()=>orders.value.filter(o=>(statusFilter.value==='all'||o.status===statusFilter.value)&&(gameFilter.value==='all'||o.gameId===gameFilter.value)&&[o.id,o.bossName,o.playerName,o.gameName].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())));
const pagedOrders=computed(()=>filteredOrders.value.slice((currentPage.value-1)*pageSize,currentPage.value*pageSize));
const filteredPlayers=computed(()=>players.value.filter(p=>(playerFilter.value==='all'||(playerFilter.value==='pending'?!p.approved:playerFilter.value==='online'?p.available&&p.approved:!p.available&&p.approved))&&[p.name,p.subtitle,...p.tags].join(' ').toLowerCase().includes(query.value.toLowerCase())&&(gameFilter.value==='all'||p.gameIds.includes(gameFilter.value))));
const filteredRefunds=computed(()=>orders.value.filter(o=>o.refundStatus!=='none'&&(refundFilter.value==='all'||o.refundStatus===refundFilter.value)&&[o.id,o.bossName,o.playerName].join(' ').includes(query.value)));
const filteredSettlements=computed(()=>settlements.value.filter(s=>settlementFilter.value==='all'||s.status===settlementFilter.value));
const eligibleOrders=computed(()=>orders.value.filter(o=>o.status==='completed'&&o.refundStatus!=='pending'&&!o.settlementId&&o.earnings>0));
const pendingAmount=computed(()=>eligibleOrders.value.reduce((n,o)=>n+o.earnings,0));
const batchedAmount=computed(()=>settlements.value.filter(s=>s.status==='pending').reduce((n,s)=>n+s.amount,0));
const paidAmount=computed(()=>settlements.value.filter(s=>s.status==='paid').reduce((n,s)=>n+s.amount,0));
const customers=computed(()=>Array.from(new Set(orders.value.map(o=>o.bossId))).map(id=>{const list=orders.value.filter(o=>o.bossId===id);return {id,name:list[0].bossName,count:list.length,total:list.filter(o=>o.paidAt).reduce((n,o)=>n+o.amount-(o.refundStatus==='refunded'?o.refundAmount||0:0),0),last:Math.max(...list.map(o=>o.createdAt)),active:list.filter(o=>['waiting','accepted','serving','confirming'].includes(o.status)).length,refunds:list.filter(o=>o.refundStatus==='pending').length};}).filter(c=>[c.name,c.id].join(' ').includes(query.value)));
const selectedCustomer=computed(()=>customers.value.find(c=>c.id===customerId.value));
const customerOrders=computed(()=>orders.value.filter(o=>o.bossId===customerId.value));
const matchingPlayers=computed(()=>players.value.filter(p=>p.approved&&p.available&&p.gameIds.includes(selectedOrder.value?.gameId||'')));
const gameBy=(id:string)=>games.value.find(g=>g.id===id);
const playerBusy=(id:string)=>orders.value.some(o=>o.playerId===id&&['accepted','serving','confirming'].includes(o.status)&&o.id!==selectedOrder.value?.id);
const formatDate=computed(()=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(Date.now()));
const trendMax=computed(()=>Math.max(...(dashboard.value?.revenueTrend.map(d=>d.revenue)||[0]),10000));
const trendPoints=computed(()=>dashboard.value?.revenueTrend.map((d,i)=>`${55+i*90},${192-d.revenue/trendMax.value*150}`).join(' ')||'');
const chartArea=computed(()=>`M 55 200 L ${trendPoints.value.split(' ').join(' L ')} L 595 200 Z`);
const totalGameOrders=computed(()=>dashboard.value?.gameDistribution.reduce((n,g)=>n+g.orders,0)||0);
const ringStyle=computed(()=>{let start=0;const stops=dashboard.value?.gameDistribution.map(g=>{const end=start+g.orders/(totalGameOrders.value||1)*100;const v=`${g.color} ${start}% ${end}%`;start=end;return v;});return {background:`conic-gradient(${stops?.join(',')||'#eee 0% 100%'})`};});
watch([query,gameFilter,statusFilter],()=>currentPage.value=1);
function navigate(id:string){page.value=id;location.hash=id;query.value='';gameFilter.value='all';statusFilter.value='all';currentPage.value=1;}
function onHash(){const id=location.hash.slice(1);if(availableNav.value.some(n=>n.id===id))page.value=id;}
async function load(silent=false){if(refreshing.value)return;refreshing.value=true;if(!silent)loading.value=true;try{if(!staff.session)await staff.login('admin');const [o,p,g,d,s]=await Promise.all([api.orders({scope:'all'}),api.players(),api.games(),api.dashboard(),api.settings()]);orders.value=o;players.value=p;games.value=g;dashboard.value=d;settings.value=s;if(canFinance.value)settlements.value=await api.settlements();else settlements.value=[];if(isAdmin.value)audit.value=await api.audit();else audit.value=[];if(selectedOrder.value)selectedOrder.value=orders.value.find(o=>o.id===selectedOrder.value?.id)||selectedOrder.value;loadError.value='';}catch(e){if(e instanceof ApiError&&e.code===401){await staff.login(staff.session?.role||'admin');refreshing.value=false;await load(silent);return;}loadError.value=e instanceof Error?e.message:'数据加载失败';}finally{loading.value=false;refreshing.value=false;}}
async function run(job:()=>Promise<void>){if(busy.value)return;busy.value=true;try{await job();}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'操作失败');}finally{busy.value=false;}}
function openOrder(o:Order){selectedOrder.value=o;orderDrawer.value=true;}
function openAssign(o:Order){selectedOrder.value=o;assignPlayer.value='';assignReason.value='';assignDialog.value=true;}
async function submitAssign(){await run(async()=>{if(!assignPlayer.value){ElMessage.warning('请选择打手');return;}await api.act(selectedOrder.value!.id,'assign',{playerId:assignPlayer.value,reason:assignReason.value});assignDialog.value=false;await load(true);ElMessage.success('派单成功，两端订单已同步');});}
function openReview(o:Order,approve:boolean){selectedOrder.value=o;reviewApprove.value=approve;reviewNote.value='';refundDialog.value=true;}
async function submitReview(){await run(async()=>{await api.act(selectedOrder.value!.id,'review-refund',{approve:reviewApprove.value,note:reviewNote.value});refundDialog.value=false;await load(true);ElMessage.success(reviewApprove.value?'已模拟原路退款，报酬已调整':'已拒绝退款申请');});}
async function requestRefund(o:Order){await run(async()=>{const {value}=await ElMessageBox.prompt('请填写退款原因（至少 5 字），将发起全额退款申请交由财务审核。','客服发起售后',{inputType:'textarea',inputPlaceholder:'例如：客户申请取消，尚未开始服务',confirmButtonText:'提交申请',cancelButtonText:'取消',inputValidator:(v:string)=>v?.trim().length>=5||'请填写至少 5 字原因'});await api.act(o.id,'refund',{reason:value,amount:o.amount});await load(true);ElMessage.success('已提交退款申请');});}
async function cancelOrder(o:Order){await run(async()=>{await ElMessageBox.confirm('确认关闭这笔未支付订单？','取消订单',{confirmButtonText:'确认取消',cancelButtonText:'返回'});await api.act(o.id,'cancel');await load(true);ElMessage.success('订单已取消');});}
function editPlayer(p:Player){selectedPlayer.value=p;editPrice.value=p.price/100;playerDialog.value=true;}
async function savePlayer(){await run(async()=>{await api.updatePlayer(selectedPlayer.value!.id,{price:Math.round(editPrice.value*100)});playerDialog.value=false;await load(true);ElMessage.success('单价已更新，仅对新订单生效');});}
async function togglePlayer(p:Player){await run(async()=>{await api.updatePlayer(p.id,{available:!p.available});await load(true);ElMessage.success(p.available?'已暂停接单':'已开启接单');});}
async function approvePlayer(p:Player){await run(async()=>{await api.updatePlayer(p.id,{approved:true});await load(true);ElMessage.success(`${p.name}的资料已审核通过`);});}
async function generateBatches(){await run(async()=>{await ElMessageBox.confirm(`将为 ${eligibleOrders.value.length} 笔已完成且无待审售后的订单生成结算批次，合计 ¥${money(pendingAmount.value)}。`,'生成结算批次',{confirmButtonText:'确认生成',cancelButtonText:'取消'});const result=await api.createSettlements();await load(true);ElMessage.success(`已生成 ${result.length} 个结算批次`);});}
async function payBatch(batch:Settlement){await run(async()=>{await ElMessageBox.confirm(`将模拟向 ${batch.playerName} 支付 ¥${money(batch.amount)}，不会产生真实转账。`,'确认模拟结算付款',{confirmButtonText:'确认模拟付款',cancelButtonText:'取消'});await api.paySettlement(batch.id);await load(true);ElMessage.success('模拟付款已完成，打手端报酬已更新');});}
function openSettings(){if(settings.value)Object.assign(settingsForm,{...settings.value,commissionPercent:settings.value.commissionBps/100});}
watch(page,(p)=>{if(p==='settings')openSettings();});
async function saveSettings(){await run(async()=>{const result=await api.updateSettings({name:settingsForm.name,commissionBps:Math.round(settingsForm.commissionPercent*100),unpaidTimeoutMinutes:settingsForm.unpaidTimeoutMinutes,announcement:settingsForm.announcement});await load(true);Object.assign(settingsForm,{...result,commissionPercent:result.commissionBps/100});ElMessage.success('设置已保存，两端已同步');});}
async function resetDemo(){if(resetting.value)return;resetting.value=true;try{await ElMessageBox.confirm('将清除当前浏览器中新增和修改的模拟业务数据，并恢复样例。此操作不影响真实业务。','重置模拟数据',{confirmButtonText:'确认重置',cancelButtonText:'取消',type:'warning'});await api.reset();await load(true);openSettings();ElMessage.success('已恢复初始演示数据');}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'重置失败');}finally{resetting.value=false;}}
async function switchRole(role:Role){await run(async()=>{await staff.login(role);roleDialog.value=false;if(!availableNav.value.some(n=>n.id===page.value))navigate('dashboard');await load(true);ElMessage.success(`已切换为${roleLabels[role]}，操作权限同步更新`);});}
function exportCsv(kind='orders'){
  let rows:(string|number)[][];
  if(kind==='settlements')rows=[['结算单号','打手','订单数','金额（元）','状态'],...filteredSettlements.value.map(s=>[s.id,s.playerName,s.orderIds.length,money(s.amount),s.status==='paid'?'已付款':'待付款'])];
  else rows=[['订单号','老板','游戏','区服','打手','时长（小时）','金额（元）','状态','售后状态','创建时间'],...filteredOrders.value.map(o=>[o.id,o.bossName,o.gameName,o.region,o.playerName||'待接单',o.quantity,money(o.amount),statusLabels[o.status],o.refundStatus,time(o.createdAt)])];
  const escape=(v:string|number)=>{const text=String(v).replace(/^[=+\-@]/,"'$&");return '"'+text.replace(/"/g,'""')+'"';};
  const blob=new Blob(['\ufeff'+rows.map(row=>row.map(escape).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`星曜电竞-${kind==='settlements'?'结算':'订单'}-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(url);ElMessage.success('CSV 已导出');
}
function openMobile(){window.open('/mobile/#/pages/index/index','_blank');}
function doSearch(){navigate('orders');query.value=globalSearch.value;globalSearch.value='';}
onMounted(async()=>{await load();if(!availableNav.value.some(n=>n.id===page.value))navigate('dashboard');if(page.value==='settings')openSettings();refreshTimer=setInterval(()=>load(true),12000);window.addEventListener('hashchange',onHash);window.addEventListener('storage',onStorage);});
function onStorage(e:StorageEvent){if(e.key==='stellar-club:database:v1')load(true);}
onUnmounted(()=>{clearInterval(refreshTimer);window.removeEventListener('hashchange',onHash);window.removeEventListener('storage',onStorage);});
</script>

<template>
  <div class="admin-app">
    <aside class="sidebar" :class="{collapsed:sidebarCollapsed}"><div class="brand"><span class="brand-symbol">✳</span><div>{{settings?.name||'星曜电竞'}}<small>STELLAR CLUB</small></div></div><div class="workspace"><div class="workspace-icon">S</div><div><strong>俱乐部工作空间</strong><small>CLUB WORKSPACE</small></div><el-icon><ArrowDown/></el-icon></div><div class="nav-caption">运营管理 <span>WORKSPACE</span></div><nav><button v-for="n in availableNav" :key="n.id" :class="{active:page===n.id}" @click="navigate(n.id)"><el-icon><component :is="n.icon"/></el-icon><span>{{n.label}}</span><span v-if="n.id==='orders'&&dashboard?.unassigned" class="nav-count">{{dashboard.unassigned}}</span><span v-if="n.id==='refunds'&&pendingRefunds.length" class="nav-count warning-count">{{pendingRefunds.length}}</span></button></nav><div class="sidebar-bottom"><div class="mobile-entry"><div class="entry-icon"><el-icon><Monitor/></el-icon></div><strong>去看看玩家的世界</strong><p>老板与打手 H5，一键切换视角。</p><button @click="openMobile">打开移动端 <el-icon><TopRight/></el-icon></button></div><button class="staff-card" @click="roleDialog=true"><div class="staff-avatar">{{staff.session?.name.slice(0,1)||'陈'}}</div><div><strong>{{staff.session?.name||'陈安'}}<span>{{staff.session?roleLabels[staff.session.role]:'管理员'}}</span></strong><small>切换演示身份</small></div><el-icon><Switch/></el-icon></button></div></aside>
    <div class="main-shell"><header class="top-header"><div class="breadcrumb"><button class="sidebar-toggle" aria-label="切换侧栏" @click="sidebarCollapsed=!sidebarCollapsed"><el-icon><Grid/></el-icon></button><span>工作空间</span><el-icon><ArrowRight/></el-icon><strong>{{pageLabel}}</strong></div><div class="header-actions"><div class="global-search"><el-icon><Search/></el-icon><input v-model="globalSearch" placeholder="搜索订单号、客户或打手" @keyup.enter="doSearch"/><kbd>↵</kbd></div><span class="environment"><i/> 模拟环境</span><el-popover placement="bottom-end" :width="320" trigger="click"><template #reference><button class="notification-button" aria-label="查看待办提醒"><el-icon><Bell/></el-icon><i v-if="pendingRefunds.length"/></button></template><div class="notification-panel"><strong>待办提醒</strong><p>{{pendingRefunds.length}} 笔退款申请等待审核，{{dashboard?.unassigned||0}} 笔订单等待接单。</p><el-button size="small" @click="navigate('refunds')">查看退款售后</el-button><el-button size="small" @click="navigate('orders');statusFilter='waiting'">查看待派订单</el-button></div></el-popover><button class="header-avatar" @click="roleDialog=true">{{staff.session?.name.slice(0,1)||'陈'}}</button></div></header>
    <div class="demo-bar"><div><span class="demo-badge">DEMO</span> 前端交互演示 · 所有登录、收付款和接口均为模拟，同一浏览器内共享数据。</div><button @click="openMobile">打开 H5 联动体验 <el-icon><TopRight/></el-icon></button></div>
    <main class="main-content" v-loading="loading"><el-alert v-if="loadError" :title="loadError" type="error" show-icon :closable="false"><el-button link @click="load()">重新加载</el-button></el-alert>
      <div class="page-top"><div><div class="page-eyebrow">{{page==='dashboard'?'YOUR CLUB, AT A GLANCE':'STELLAR CLUB / OPERATIONS'}}</div><h1>{{page==='dashboard'?'俱乐部的今天，从这里开始。':pageLabel}}<span v-if="page==='dashboard'" class="greeting-sun">✳</span></h1><p>{{page==='dashboard'?`欢迎回来，${staff.session?.name||'陈安'}。每一份热爱，都值得认真经营。`:({orders:'从下单到完成，让每一次服务都有迹可循。',players:'找到合适的队友，也让每一份实力被看见。',customers:'了解每一位玩家，建立更长久的信任。',refunds:'认真回应每一个问题，让服务安心收尾。',settlements:'每一笔报酬清楚可查，每一份付出都有回响。',settings:'把俱乐部的服务规则，设置得清清楚楚。',audit:'重要操作完整留痕，让协作更透明。'} as Record<string,string>)[page]}}</p></div><div class="page-top-actions"><span v-if="page==='dashboard'" class="today-date"><el-icon><Clock/></el-icon>{{formatDate}}</span><el-button v-if="page==='orders'" :icon="Download" @click="exportCsv()">导出订单</el-button><el-button v-if="page==='settlements'" :icon="Download" @click="exportCsv('settlements')">导出结算</el-button><el-button v-if="page==='settlements'" type="primary" :icon="Plus" :disabled="!eligibleOrders.length||busy" @click="generateBatches">生成结算批次</el-button><el-button :icon="Refresh" :loading="refreshing" @click="load(true)">{{page==='dashboard'?'刷新数据':'刷新'}}</el-button></div></div>

      <template v-if="page==='dashboard' && dashboard">
        <div class="stats-grid"><div class="stat-card revenue-card"><div class="stat-head">今日实收（元）<div class="stat-icon green"><el-icon><CreditCard/></el-icon></div></div><div class="stat-value"><span>¥</span>{{compactMoney(dashboard.todayRevenue)}}</div><div class="stat-foot"><span class="stat-note">已扣除已完成退款</span><span class="tiny-chart">▁▂▁▃▂▅▄▆▅█</span></div></div><div class="stat-card"><div class="stat-head">今日新增订单<div class="stat-icon purple"><el-icon><Tickets/></el-icon></div></div><div class="stat-value">{{dashboard.todayOrders}}<small>笔</small></div><div class="stat-foot"><span class="stat-chip purple-chip">{{dashboard.liveOrders}} 笔服务流转中</span><button @click="navigate('orders')">查看订单 <el-icon><ArrowRight/></el-icon></button></div></div><div class="stat-card"><div class="stat-head">在线打手<div class="stat-icon blue"><el-icon><UserFilled/></el-icon></div></div><div class="stat-value">{{dashboard.onlinePlayers}}<small>/ {{dashboard.totalPlayers}} 人</small></div><div class="stat-foot"><span class="stat-chip green-chip"><i/> {{dashboard.availablePlayers}} 位可立即接单</span><button @click="navigate('players')"><el-icon><ArrowRight/></el-icon></button></div></div><div class="stat-card"><div class="stat-head">待处理售后<div class="stat-icon orange"><el-icon><Service/></el-icon></div></div><div class="stat-value">{{dashboard.refundPending}}<small>笔</small></div><div class="stat-foot"><span class="stat-note">及时回应，安心服务</span><button class="orange-link" @click="navigate('refunds')">去处理 <el-icon><ArrowRight/></el-icon></button></div></div></div>
        <div class="dashboard-middle"><section class="panel revenue-panel"><div class="panel-heading"><div><h2>经营趋势 <span>REVENUE OVERVIEW</span></h2><p>最近 7 天订单净收款，按订单创建日归集</p></div><span class="date-range">最近 7 天</span></div><div class="chart-legend"><span><i class="legend-dot"/>订单净收款</span><strong>¥{{compactMoney(dashboard.revenueTrend.reduce((n,d)=>n+d.revenue,0))}}</strong><span class="legend-muted">合计</span></div><div class="line-chart"><svg viewBox="0 0 640 232" role="img" aria-label="最近七天订单净收款趋势"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#8172de" stop-opacity=".23"/><stop offset="100%" stop-color="#8172de" stop-opacity=".01"/></linearGradient></defs><g v-for="i in 5" :key="i"><line x1="55" x2="610" :y1="200-(i-1)*40" :y2="200-(i-1)*40" stroke="#e9ebf0" stroke-dasharray="4 5"/><text x="0" :y="204-(i-1)*40" fill="#9b9eaa" font-size="10">{{compactMoney((i-1)*trendMax/4)}}</text></g><path :d="chartArea" fill="url(#areaFill)"/><polyline :points="trendPoints" fill="none" stroke="#8372df" stroke-width="2.8" stroke-linejoin="round" stroke-linecap="round"/><g v-for="(d,i) in dashboard.revenueTrend" :key="d.label"><circle :cx="55+i*90" :cy="192-d.revenue/trendMax*150" r="4" fill="#fff" stroke="#8372df" stroke-width="2"><title>{{d.label}}：¥{{money(d.revenue)}} / {{d.orders}} 笔</title></circle><text :x="55+i*90" y="226" text-anchor="middle" fill="#969aa7" font-size="10">{{d.label}}</text></g></svg></div></section><section class="panel distribution-panel"><div class="panel-heading"><div><h2>大家都在玩</h2><p>已付款订单的游戏分布</p></div><el-icon class="muted-icon"><TrendCharts/></el-icon></div><div class="donut-wrap"><div class="donut" :style="ringStyle"><div><strong>{{totalGameOrders}}</strong><span>已付款订单</span></div></div><span class="donut-decoration">✳</span></div><div class="game-legend"><div v-for="g in dashboard.gameDistribution" :key="g.name"><span class="legend-name"><i :style="{background:g.color}"/>{{g.name}}</span><strong>{{g.orders}} <small>笔</small></strong><span>{{Math.round(g.orders/(totalGameOrders||1)*100)}}%</span></div></div></section></div>
        <div class="dashboard-bottom"><section class="panel latest-panel"><div class="panel-heading"><div><h2>最新订单 <span class="count-soft">{{orders.length}}</span></h2><p>每一场好游戏，都从这里出发</p></div><button class="panel-link" @click="navigate('orders')">全部订单 <el-icon><ArrowRight/></el-icon></button></div><el-table :data="dashboard.recentOrders" class="clean-table" @row-click="openOrder"><el-table-column label="订单 / 游戏" min-width="180"><template #default="{row}"><div class="table-game"><div class="game-tile" :style="{background:gameBy(row.gameId)?.color+'19',color:gameBy(row.gameId)?.color}">{{gameBy(row.gameId)?.short}}</div><div><strong>{{row.gameName}}</strong><small>{{row.id}}</small></div></div></template></el-table-column><el-table-column label="老板 / 打手" min-width="130"><template #default="{row}"><span class="table-person">{{row.bossName}}<span class="person-divider">/</span>{{row.playerName||'待接单'}}</span></template></el-table-column><el-table-column label="金额" width="92"><template #default="{row}"><strong class="table-money">¥{{money(row.amount)}}</strong></template></el-table-column><el-table-column label="状态" width="112"><template #default="{row}"><span class="status-badge" :class="row.refundStatus==='pending'?'refund':row.status"><i/>{{row.refundStatus==='pending'?'售后处理中':statusLabels[row.status as keyof typeof statusLabels]}}</span></template></el-table-column><el-table-column label="" width="45"><template #default><el-icon class="muted-icon"><ArrowRight/></el-icon></template></el-table-column></el-table></section><section class="panel activity-panel"><div class="panel-heading"><div><h2>工作动态</h2><p>团队协作，实时留痕</p></div><el-icon class="muted-icon"><Clock/></el-icon></div><div class="activity-list"><div v-for="(a,i) in dashboard.activity.slice(0,4)" :key="a.id" class="activity-item"><div class="activity-dot" :class="'dot-'+i"><el-icon><component :is="i===0?Service:i===1?Select:i===2?User:Check"/></el-icon></div><div><strong>{{a.actor}} <span>{{a.action}}</span></strong><p>{{a.detail}}</p><small>{{time(a.at)}}</small></div></div><div v-if="!dashboard.activity.length" class="blank-text">暂时没有操作记录</div></div></section></div>
        <div class="dashboard-footer"><span><i/> 数据来自当前浏览器的模拟服务</span><span>热爱有回响，经营有方向。<span class="footer-star">✳</span></span></div>
      </template>

      <template v-else-if="page==='orders'">
        <div class="summary-strip"><div><span>全部订单</span><strong>{{orders.length}}</strong></div><div><span>待接单</span><strong class="purple-text">{{orders.filter(o=>o.status==='waiting').length}}</strong></div><div><span>服务流转中</span><strong>{{orders.filter(o=>['accepted','serving','confirming'].includes(o.status)).length}}</strong></div><div><span>已完成</span><strong>{{orders.filter(o=>o.status==='completed').length}}</strong></div></div>
        <section class="panel order-panel"><div class="table-tabs"><button v-for="f in [{id:'all',label:'全部订单'},...Object.entries(statusLabels).map(([id,label])=>({id,label}))]" :key="f.id" :class="{active:statusFilter===f.id}" @click="statusFilter=f.id">{{f.label}}<span>{{f.id==='all'?orders.length:orders.filter(o=>o.status===f.id).length}}</span></button></div><div class="table-toolbar"><el-input v-model="query" :prefix-icon="Search" placeholder="搜索订单号、老板、打手" clearable class="search-input"/><el-select v-model="gameFilter" class="game-select"><el-option label="全部游戏" value="all"/><el-option v-for="g in games" :key="g.id" :label="g.name" :value="g.id"/></el-select><span class="result-count">共 {{filteredOrders.length}} 笔订单</span><el-button text :icon="Refresh" @click="query='';gameFilter='all';statusFilter='all'">重置筛选</el-button></div><el-table :data="pagedOrders" empty-text="没有匹配的订单，请调整筛选条件"><el-table-column label="订单 / 创建时间" min-width="190"><template #default="{row}"><button class="order-id-link" @click="openOrder(row)">{{row.id}}</button><div class="cell-sub">{{time(row.createdAt)}}</div></template></el-table-column><el-table-column label="游戏 / 区服" min-width="160"><template #default="{row}"><div class="table-game"><div class="game-tile small-tile" :style="{background:gameBy(row.gameId)?.color+'19',color:gameBy(row.gameId)?.color}">{{gameBy(row.gameId)?.short}}</div><div><strong>{{row.gameName}}</strong><small>{{row.region}} · {{row.quantity}} 小时</small></div></div></template></el-table-column><el-table-column label="老板" min-width="80" prop="bossName"/><el-table-column label="打手" min-width="90"><template #default="{row}"><span :class="{'cell-muted':!row.playerName}">{{row.playerName||'待接单'}}</span></template></el-table-column><el-table-column label="金额" width="100"><template #default="{row}"><strong class="table-money">¥{{money(row.amount)}}</strong></template></el-table-column><el-table-column label="状态" width="118"><template #default="{row}"><span class="status-badge" :class="row.status"><i/>{{statusLabels[row.status as keyof typeof statusLabels]}}</span><div v-if="row.refundStatus==='pending'" class="refund-hint">售后处理中</div></template></el-table-column><el-table-column label="操作" min-width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openOrder(row)">详情</el-button><el-button v-if="canDispatch&&['waiting','accepted'].includes(row.status)&&row.refundStatus!=='pending'" link type="primary" @click="openAssign(row)">{{row.playerId?'改派':'派单'}}</el-button><el-button v-if="canDispatch&&row.status==='unpaid'" link @click="cancelOrder(row)">取消</el-button></template></el-table-column></el-table><div class="table-pagination"><span>显示第 {{filteredOrders.length?((currentPage-1)*pageSize+1):0}}～{{Math.min(currentPage*pageSize,filteredOrders.length)}} 条，共 {{filteredOrders.length}} 条</span><el-pagination v-model:current-page="currentPage" :page-size="pageSize" :total="filteredOrders.length" layout="prev, pager, next" background/></div></section>
      </template>

      <template v-else-if="page==='players'"><div class="summary-strip"><div><span>打手总数</span><strong>{{players.length}}</strong></div><div><span>已审核</span><strong>{{players.filter(p=>p.approved).length}}</strong></div><div><span>待审核</span><strong class="orange-text">{{players.filter(p=>!p.approved).length}}</strong></div><div><span>可接单状态</span><strong class="purple-text">{{onlinePlayers.length}}</strong></div></div><section class="panel"><div class="table-tabs"><button v-for="f in [{id:'all',label:'全部打手'},{id:'online',label:'可接单'},{id:'rest',label:'休息中'},{id:'pending',label:'待审核'}]" :key="f.id" :class="{active:playerFilter===f.id}" @click="playerFilter=f.id">{{f.label}}</button></div><div class="table-toolbar"><el-input v-model="query" :prefix-icon="Search" clearable placeholder="搜索昵称、技能或标签" class="search-input"/><el-select v-model="gameFilter" class="game-select"><el-option label="全部游戏" value="all"/><el-option v-for="g in games" :key="g.id" :label="g.name" :value="g.id"/></el-select><span class="result-count">共 {{filteredPlayers.length}} 位打手</span></div><el-table :data="filteredPlayers" empty-text="没有匹配的打手"><el-table-column label="打手" min-width="170"><template #default="{row}"><div class="table-game"><div class="player-avatar" :style="{background:row.color}">{{row.avatar}}</div><div><strong>{{row.name}}</strong><small>{{row.id.toUpperCase()}} · {{row.approved?'认证打手':'资料待审核'}}</small></div></div></template></el-table-column><el-table-column label="擅长游戏" min-width="160"><template #default="{row}"><div class="game-tags"><span v-for="id in row.gameIds" :key="id">{{gameBy(id)?.name}}</span></div></template></el-table-column><el-table-column label="时薪" width="100"><template #default="{row}">¥{{money(row.price)}}</template></el-table-column><el-table-column label="评分 / 历史订单" min-width="130"><template #default="{row}"><span class="rating-star">★</span> {{row.rating}}<div class="cell-sub">历史 {{row.completed}} 单</div></template></el-table-column><el-table-column label="接单状态" width="110"><template #default="{row}"><span class="status-badge" :class="!row.approved?'unpaid':row.available?'completed':'cancelled'"><i/>{{!row.approved?'待审核':row.available?'可接单':'休息中'}}</span></template></el-table-column><el-table-column label="操作" min-width="180"><template #default="{row}"><template v-if="isAdmin"><el-button v-if="!row.approved" link type="primary" :disabled="busy" @click="approvePlayer(row)">审核通过</el-button><el-button v-else link type="primary" :disabled="busy" @click="togglePlayer(row)">{{row.available?'暂停接单':'开启接单'}}</el-button><el-button link @click="editPlayer(row)">调整单价</el-button></template><span v-else class="cell-muted">只读查看</span></template></el-table-column></el-table><div class="panel-footnote">历史评分与订单数为档案样例；订单和报酬数据由模拟接口实时计算。修改单价不影响已创建订单。</div></section></template>

      <template v-else-if="page==='customers'"><section class="panel"><div class="table-toolbar"><el-input v-model="query" :prefix-icon="Search" class="search-input" clearable placeholder="搜索客户姓名或编号"/><span class="result-count">共 {{customers.length}} 位客户</span></div><el-table :data="customers" empty-text="没有找到匹配的客户"><el-table-column label="客户" min-width="200"><template #default="{row}"><div class="table-game"><div class="customer-avatar">{{row.name.slice(0,1)}}</div><div><strong>{{row.name}}</strong><small>{{row.id}}</small></div></div></template></el-table-column><el-table-column label="累计订单" prop="count"/><el-table-column label="累计净支付" min-width="130"><template #default="{row}"><strong>¥{{money(row.total)}}</strong></template></el-table-column><el-table-column label="进行中" prop="active"/><el-table-column label="待处理售后" prop="refunds"/><el-table-column label="最近下单" min-width="150"><template #default="{row}">{{time(row.last)}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" @click="customerId=row.id;customerDrawer=true">查看订单</el-button></template></el-table-column></el-table><div class="panel-footnote">演示客户由订单自动汇总。当前展示 2 位样例老板，新建订单会同步更新统计。</div></section></template>

      <template v-else-if="page==='refunds'"><div class="summary-strip"><div><span>待审核退款</span><strong class="orange-text">{{pendingRefunds.length}}</strong></div><div><span>待审核金额</span><strong>¥{{money(pendingRefunds.reduce((n,o)=>n+(o.refundAmount||0),0))}}</strong></div><div><span>已模拟退款</span><strong>{{orders.filter(o=>o.refundStatus==='refunded').length}} <small>笔</small></strong></div><div><span>已退款金额</span><strong>¥{{money(orders.filter(o=>o.refundStatus==='refunded').reduce((n,o)=>n+(o.refundAmount||0),0))}}</strong></div></div><section class="panel"><div class="table-tabs"><button v-for="f in [{id:'pending',label:'待审核'},{id:'refunded',label:'已退款'},{id:'rejected',label:'未通过'},{id:'all',label:'全部售后'}]" :key="f.id" :class="{active:refundFilter===f.id}" @click="refundFilter=f.id">{{f.label}}</button></div><div class="table-toolbar"><el-input v-model="query" :prefix-icon="Search" class="search-input" clearable placeholder="搜索订单、老板或打手"/><span class="result-count">{{canFinance?'你可以审核并模拟退款':'当前为客服视角，可查看售后，财务或管理员可审核'}}</span></div><el-table :data="filteredRefunds" empty-text="当前没有这类售后申请"><el-table-column label="关联订单" min-width="185"><template #default="{row}"><button class="order-id-link" @click="openOrder(row)">{{row.id}}</button><div class="cell-sub">{{row.gameName}} · {{row.bossName}}</div></template></el-table-column><el-table-column label="申请金额" width="120"><template #default="{row}"><strong class="orange-text">¥{{money(row.refundAmount||0)}}</strong><div class="cell-sub">实付 ¥{{money(row.amount)}}</div></template></el-table-column><el-table-column label="退款原因" min-width="240"><template #default="{row}"><div class="reason-cell">{{row.refundReason}}</div><div v-if="row.refundReviewNote" class="cell-sub">审核：{{row.refundReviewNote}}</div></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><span class="status-badge" :class="row.refundStatus==='pending'?'unpaid':row.refundStatus==='refunded'?'completed':'cancelled'"><i/>{{row.refundStatus==='pending'?'待审核':row.refundStatus==='refunded'?'已模拟退款':'未通过'}}</span></template></el-table-column><el-table-column label="操作" min-width="160"><template #default="{row}"><template v-if="row.refundStatus==='pending'&&canFinance"><el-button link type="primary" @click="openReview(row,true)">同意退款</el-button><el-button link type="danger" @click="openReview(row,false)">拒绝</el-button></template><el-button v-else link type="primary" @click="openOrder(row)">查看详情</el-button></template></el-table-column></el-table><div class="panel-footnote">退款均为模拟原路退回。待审核订单暂停履约及结算；部分退款通过后会按原订单抽成规则重新计算报酬。</div></section></template>

      <template v-else-if="page==='settlements'"><div class="stats-grid settlement-stats"><div class="stat-card"><div class="stat-head">可生成结算（元）<div class="stat-icon purple"><el-icon><Wallet/></el-icon></div></div><div class="stat-value"><span>¥</span>{{compactMoney(pendingAmount)}}</div><div class="stat-foot">{{eligibleOrders.length}} 笔符合条件的订单</div></div><div class="stat-card"><div class="stat-head">批次待付款（元）<div class="stat-icon orange"><el-icon><Clock/></el-icon></div></div><div class="stat-value"><span>¥</span>{{compactMoney(batchedAmount)}}</div><div class="stat-foot">{{settlements.filter(s=>s.status==='pending').length}} 个待付款批次</div></div><div class="stat-card"><div class="stat-head">已模拟结算（元）<div class="stat-icon green"><el-icon><CircleCheck/></el-icon></div></div><div class="stat-value"><span>¥</span>{{compactMoney(paidAmount)}}</div><div class="stat-foot">不会产生真实银行或微信转账</div></div></div><section class="panel"><div class="table-tabs"><button v-for="f in [{id:'all',label:'全部批次'},{id:'pending',label:'待付款'},{id:'paid',label:'已付款'}]" :key="f.id" :class="{active:settlementFilter===f.id}" @click="settlementFilter=f.id">{{f.label}}</button></div><el-table :data="filteredSettlements" empty-text="尚未生成结算批次。点击右上角按钮，从符合条件的订单生成。"><el-table-column label="结算批次" min-width="230" prop="id"/><el-table-column label="打手" prop="playerName" min-width="100"/><el-table-column label="订单数" width="90"><template #default="{row}">{{row.orderIds.length}} 笔</template></el-table-column><el-table-column label="结算金额" min-width="130"><template #default="{row}"><strong>¥{{money(row.amount)}}</strong></template></el-table-column><el-table-column label="生成时间" min-width="150"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><span class="status-badge" :class="row.status==='paid'?'completed':'unpaid'"><i/>{{row.status==='paid'?'已模拟付款':'待付款'}}</span></template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button v-if="row.status==='pending'" link type="primary" :disabled="busy" @click="payBatch(row)">确认模拟付款</el-button><span v-else class="cell-muted">{{time(row.paidAt)}}</span></template></el-table-column></el-table><div class="panel-footnote">仅统计已完成、无待审售后且未进入结算批次的订单。每笔订单只能进入一个批次，避免重复结算。</div></section><section class="panel eligible-panel"><div class="panel-heading"><div><h2>待生成结算的订单</h2><p>按订单保存的价格和服务费规则计算</p></div><span class="count-soft">{{eligibleOrders.length}} 笔</span></div><el-table :data="eligibleOrders" empty-text="暂无可结算订单"><el-table-column label="订单号" prop="id" min-width="190"/><el-table-column label="打手" prop="playerName"/><el-table-column label="游戏" prop="gameName"/><el-table-column label="报酬" width="150"><template #default="{row}">¥{{money(row.earnings)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="openOrder(row)">查看</el-button></template></el-table-column></el-table></section></template>

      <template v-else-if="page==='settings'"><div class="settings-layout"><section class="panel settings-panel"><div class="panel-heading"><div><h2>基础与交易设置</h2><p>修改将同步到当前浏览器的 H5；历史订单使用下单时的规则。</p></div><el-icon class="muted-icon"><Setting/></el-icon></div><el-form label-position="top" :model="settingsForm"><el-form-item label="俱乐部名称"><el-input v-model="settingsForm.name" :maxlength="20" show-word-limit/></el-form-item><el-form-item label="平台服务费比例"><el-input-number v-model="settingsForm.commissionPercent" :min="0" :max="50" :precision="0"/><span class="form-suffix">%</span><div class="form-help">例如：订单实付 100 元，服务费 20%，打手报酬为 80 元。</div></el-form-item><el-form-item label="待支付订单自动关闭"><el-select v-model="settingsForm.unpaidTimeoutMinutes"><el-option v-for="n in [5,10,15,30]" :key="n" :label="`${n} 分钟`" :value="n"/></el-select></el-form-item><el-form-item label="俱乐部公告"><el-input v-model="settingsForm.announcement" type="textarea" :rows="4" :maxlength="120" show-word-limit/></el-form-item><el-button type="primary" :loading="busy" @click="saveSettings">保存设置</el-button></el-form></section><div><section class="panel integration-card"><div class="integration-icon"><el-icon><Link/></el-icon></div><h2>服务接入状态</h2><p>接口位置已预留，当前运行在 Mock 模式。</p><div v-for="name in ['微信网页授权','微信 JSAPI / H5 支付','退款与结算','订单与打手服务']" :key="name" class="integration-row"><span>{{name}}</span><span class="mock-tag">模拟实现</span></div><div class="integration-note">切换真实 API Transport 即可连接后端。移动端业务保留小程序适配边界。</div></section><section class="panel reset-card"><h2>演示数据</h2><p>恢复最初的样例订单、打手和结算状态。仅影响当前浏览器。</p><el-button :loading="resetting" @click="resetDemo">重置模拟数据</el-button></section></div></div></template>

      <template v-else-if="page==='audit'"><section class="panel"><div class="panel-heading"><div><h2>操作记录</h2><p>订单、派单、退款、结算和配置修改均保留操作记录。</p></div><span class="count-soft">{{audit.length}} 条</span></div><el-table :data="audit" empty-text="暂无操作日志"><el-table-column label="操作时间" min-width="150"><template #default="{row}">{{time(row.at)}}</template></el-table-column><el-table-column label="操作人" prop="actor" min-width="130"/><el-table-column label="动作" min-width="130"><template #default="{row}"><span class="audit-action">{{row.action}}</span></template></el-table-column><el-table-column label="关联对象" prop="target" min-width="220"/><el-table-column label="说明" prop="detail" min-width="280"/></el-table><div class="panel-footnote">演示环境最多保留最近 300 条操作记录。生产环境应由服务端持久化并控制审计访问权限。</div></section></template>
    </main>
    </div>

    <el-drawer v-model="orderDrawer" title="订单详情" size="500px" class="order-drawer"><template v-if="selectedOrder"><div class="drawer-status"><span class="status-badge" :class="selectedOrder.status"><i/>{{statusLabels[selectedOrder.status]}}</span><span v-if="selectedOrder.refundStatus==='pending'" class="status-badge refund">售后处理中</span><h2>{{selectedOrder.gameName}} · {{selectedOrder.quantity}} 小时</h2><p>{{selectedOrder.id}}</p></div><div class="drawer-amount"><span>订单金额</span><strong>¥{{money(selectedOrder.amount)}}</strong></div><div class="detail-grid"><div><span>老板</span><strong>{{selectedOrder.bossName}}</strong></div><div><span>服务打手</span><strong>{{selectedOrder.playerName||selectedOrder.preferredPlayerName||'等待接单'}}</strong></div><div><span>游戏区服</span><strong>{{selectedOrder.region}}</strong></div><div><span>下单时间</span><strong>{{time(selectedOrder.createdAt)}}</strong></div><div><span>服务费比例</span><strong>{{selectedOrder.commissionBps/100}}%</strong></div><div><span>打手预计报酬</span><strong>¥{{money(selectedOrder.earnings)}}</strong></div></div><div v-if="selectedOrder.note" class="drawer-note"><strong>老板备注</strong><p>{{selectedOrder.note}}</p></div><div v-if="selectedOrder.refundStatus!=='none'" class="drawer-refund"><strong>售后申请 · {{selectedOrder.refundStatus==='pending'?'待审核':selectedOrder.refundStatus==='refunded'?'已模拟退款':'未通过'}}</strong><p>申请 ¥{{money(selectedOrder.refundAmount||0)}} · {{selectedOrder.refundReason}}</p><p v-if="selectedOrder.refundReviewNote">审核：{{selectedOrder.refundReviewNote}}</p></div><div class="drawer-section-title">订单动态</div><el-timeline><el-timeline-item v-for="(e,i) in selectedOrder.timeline" :key="i" :timestamp="time(e.at)+' · '+e.actor" :color="i===selectedOrder.timeline.length-1?'#8d7adf':'#d6d3e4'"><strong>{{e.label}}</strong><p v-if="e.note" class="timeline-note">{{e.note}}</p></el-timeline-item></el-timeline><div class="drawer-actions"><el-button v-if="canDispatch&&['waiting','accepted'].includes(selectedOrder.status)&&selectedOrder.refundStatus!=='pending'" type="primary" @click="openAssign(selectedOrder)">{{selectedOrder.playerId?'改派打手':'分配打手'}}</el-button><el-button v-if="canDispatch&&selectedOrder.paidAt&&!selectedOrder.settlementId&&['none','rejected'].includes(selectedOrder.refundStatus)&&selectedOrder.status!=='cancelled'" @click="requestRefund(selectedOrder)">发起退款申请</el-button><template v-if="canFinance&&selectedOrder.refundStatus==='pending'"><el-button type="primary" @click="openReview(selectedOrder,true)">同意退款</el-button><el-button @click="openReview(selectedOrder,false)">拒绝退款</el-button></template><el-button v-if="canDispatch&&selectedOrder.status==='unpaid'" @click="cancelOrder(selectedOrder)">取消未支付订单</el-button></div></template></el-drawer>
    <el-dialog v-model="assignDialog" :title="selectedOrder?.playerId?'改派服务打手':'为订单分配打手'" width="480px"><div class="dialog-order-summary"><span>{{selectedOrder?.gameName}} · {{selectedOrder?.region}}</span><strong>{{selectedOrder?.id}}</strong></div><el-form label-position="top"><el-form-item label="选择打手"><el-select v-model="assignPlayer" placeholder="选择支持该游戏且有空闲容量的打手" class="full-width"><el-option v-for="p in matchingPlayers" :key="p.id" :label="`${p.name} · ${p.subtitle}${playerBusy(p.id)?'（已有未完成订单）':''}`" :value="p.id" :disabled="playerBusy(p.id)"/></el-select></el-form-item><el-form-item label="派单备注（选填）"><el-input v-model="assignReason" type="textarea" :rows="3" :maxlength="200" placeholder="说明派单或改派原因，记录会显示在订单动态中。"/></el-form-item></el-form><template #footer><el-button @click="assignDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitAssign">确认派单</el-button></template></el-dialog>
    <el-dialog v-model="refundDialog" :title="reviewApprove?'审核并模拟退款':'拒绝退款申请'" width="470px"><div class="refund-dialog-amount"><span>申请退款金额</span><strong>¥{{money(selectedOrder?.refundAmount||0)}}</strong><p>{{selectedOrder?.refundReason}}</p></div><el-alert v-if="reviewApprove" title="确认后立即模拟原路退款，不会发生真实资金变动。" type="info" :closable="false" show-icon/><el-form label-position="top"><el-form-item label="审核说明" required><el-input v-model="reviewNote" type="textarea" :rows="3" :maxlength="200" placeholder="请填写至少 2 字的审核依据，老板可在订单详情查看。"/></el-form-item></el-form><template #footer><el-button @click="refundDialog=false">返回</el-button><el-button :type="reviewApprove?'primary':'danger'" :loading="busy" @click="submitReview">{{reviewApprove?'确认模拟退款':'确认拒绝'}}</el-button></template></el-dialog>
    <el-dialog v-model="playerDialog" title="调整打手服务单价" width="420px"><p class="dialog-description">{{selectedPlayer?.name}} · {{selectedPlayer?.subtitle}}</p><el-form label-position="top"><el-form-item label="服务单价（元 / 小时）"><el-input-number v-model="editPrice" :min="1" :max="1000" :precision="2"/></el-form-item></el-form><el-alert title="只对新订单生效，历史订单价格与报酬不变。" :closable="false" type="info"/><template #footer><el-button @click="playerDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="savePlayer">保存单价</el-button></template></el-dialog>
    <el-dialog v-model="roleDialog" title="切换员工演示身份" width="480px"><p class="dialog-description">不同身份会限制页面和接口操作权限。登录均为模拟。</p><button v-for="r in [{role:'admin',name:'陈安',label:'管理员',detail:'全部模块、规则配置与打手管理'},{role:'customer_service',name:'许知',label:'客服',detail:'查询订单、派单、发起售后申请'},{role:'finance',name:'沈禾',label:'财务',detail:'审核退款、生成结算与模拟付款'}]" :key="r.role" class="staff-role-option" :class="{selected:staff.session?.role===r.role}" :disabled="busy" @click="switchRole(r.role as Role)"><span class="staff-avatar">{{r.name.slice(0,1)}}</span><span><strong>{{r.name}} · {{r.label}}</strong><small>{{r.detail}}</small></span><el-icon><component :is="staff.session?.role===r.role?CircleCheck:ArrowRight"/></el-icon></button></el-dialog>
    <el-drawer v-model="customerDrawer" :title="selectedCustomer?.name+'的订单'" size="600px"><div class="customer-drawer-summary"><div>累计订单<strong>{{selectedCustomer?.count}}</strong></div><div>累计净支付<strong>¥{{money(selectedCustomer?.total||0)}}</strong></div></div><el-table :data="customerOrders"><el-table-column label="订单" min-width="190"><template #default="{row}"><button class="order-id-link" @click="openOrder(row)">{{row.id}}</button><div class="cell-sub">{{row.gameName}} · {{statusLabels[row.status as keyof typeof statusLabels]}}</div></template></el-table-column><el-table-column label="金额" width="110"><template #default="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column label="下单时间" min-width="150"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column></el-table></el-drawer>
  </div>
</template>
